package com.oanarinaldi.wakemeup;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.widget.*;import android.view.*;import org.json.*;
public class RingActivity extends Activity {
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 public void onCreate(Bundle b){super.onCreate(b);setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(0xfffcf7ed);getWindow().setNavigationBarColor(0xfffcf7ed);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);String id=getIntent().getStringExtra("id");JSONObject a=WakeData.find(this,id);LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setGravity(Gravity.CENTER);column.setPadding(dp(24),dp(32),dp(24),dp(32));column.setBackgroundColor(0xfffcf7ed);
  ImageView sun=new ImageView(this);try(var in=getAssets().open("art/sun.png")){sun.setImageDrawable(android.graphics.drawable.Drawable.createFromStream(in,null));}catch(Exception ignored){}sun.setScaleType(ImageView.ScaleType.FIT_CENTER);column.addView(sun,new LinearLayout.LayoutParams(dp(260),dp(260)));TextView title=new TextView(this);title.setText(id!=null&&id.startsWith("check:")?"Still awake, sunshine?":"Hello, sunshine.");title.setTextSize(34);title.setTextColor(0xff382640);title.setGravity(Gravity.CENTER);title.setTypeface(Typeface.create(Typeface.createFromAsset(getAssets(),"art/Nunito.ttf"),Typeface.BOLD));title.setPadding(0,dp(20),0,dp(24));column.addView(title);
  button(column,id!=null&&id.startsWith("check:")?"Confirm I'm awake":"Start moving",true,()->{stopService(new Intent(this,RingService.class));startActivity(new Intent(this,MainActivity.class).putExtra("alarm",id).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish();});
  if(a!=null&&a.optInt("snoozeMinutes")>0)button(column,"Snooze · "+a.optInt("snoozeMinutes")+" minutes",false,()->{RingService.snooze(this,id);finish();});
  button(column,"Stop alarm",false,()->{RingService.stop(this);finish();});setContentView(column);
 }
 void button(LinearLayout parent,String title,boolean primary,Runnable action){Button button=new Button(this);button.setText(title);button.setAllCaps(false);button.setTextSize(17);button.setTextColor(primary?Color.WHITE:0xff382640);GradientDrawable bg=new GradientDrawable();bg.setColor(primary?0xff382640:0xffffffff);bg.setCornerRadius(dp(20));button.setBackground(bg);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(58));params.setMargins(0,dp(8),0,dp(8));parent.addView(button,params);button.setOnClickListener(v->action.run());}
}
